 94	
 95	static byte *AutoAllocMemory(int *size, int default_ram, int min_ram)
 96	{
 97	    byte *zonemem;
 98	
 99	    // Allocate the zone memory.  This loop tries progressively smaller
100	    // zone sizes until a size is found that can be allocated.
101	    // If we used the -mb command line parameter, only the parameter
102	    // provided is accepted.
103	
104	    zonemem = NULL;
105	
106	    while (zonemem == NULL)
107	    {
108	        // We need a reasonable minimum amount of RAM to start.
109	
110	        if (default_ram < min_ram)
111	        {
112	            I_Error("Unable to allocate %i MiB of RAM for zone", default_ram);
113	        }
114	
115	        // Try to allocate the zone memory.
116	
117	        *size = default_ram * 1024 * 1024;
118	
119	        zonemem = malloc(*size);
120	
121	        // Failed to allocate?  Reduce zone size until we reach a size
122	        // that is acceptable.
123	
124	        if (zonemem == NULL)
125	        {
126	            default_ram -= 1;
127	        }
128	    }
129	
130	    return zonemem;
131	}
