277	// Escape special characters in the given string so that they can be
278	// safely enclosed in shell quotes.
279	
280	static char *EscapeShellString(char *string)
281	{
282	    char *result;
283	    char *r, *s;
284	
285	    // In the worst case, every character might be escaped.
286	    result = malloc(strlen(string) * 2 + 3);
287	    r = result;
288	
289	    // Enclosing quotes.
290	    *r = '"';
291	    ++r;
292	
293	    for (s = string; *s != '\0'; ++s)
294	    {
295	        // From the bash manual:
296	        //
297	        //  "Enclosing characters in double quotes preserves the literal
298	        //   value of all characters within the quotes, with the exception
299	        //   of $, `, \, and, when history expansion is enabled, !."
300	        //
301	        // Therefore, escape these characters by prefixing with a backslash.
302	
303	        if (strchr("$`\\!", *s) != NULL)
304	        {
305	            *r = '\\';
306	            ++r;
307	        }
308	
309	        *r = *s;
310	        ++r;
311	    }
312	
313	    // Enclosing quotes.
314	    *r = '"';
315	    ++r;
316	    *r = '\0';
317	
318	    return result;
319	}
